import{_ as t,o,c as a,a0 as r}from"./chunks/framework.BQvjZmTX.js";const m=JSON.parse('{"title":"Threat model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/threat-model.md","filePath":"explanation/threat-model.md"}'),n={name:"explanation/threat-model.md"};function s(i,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h1><p>What arca protects against, honestly — and what it explicitly does not.</p><h2 id="protects-against" tabindex="-1">Protects against <a class="header-anchor" href="#protects-against" aria-label="Permalink to &quot;Protects against&quot;">​</a></h2><ul><li><strong>Plaintext in the repo</strong> — code and config carry <code>arca://</code> refs, never values. There is nothing to leak in a commit, a diff, a paste, or a prompt context.</li><li><strong>Plaintext in shell history / process listings</strong> — values never enter via CLI arguments (args land in <code>~/.bash_history</code> and <code>/proc/*/cmdline</code>). <code>put</code>/<code>rotate</code> read stdin or a hidden <code>/dev/tty</code> prompt.</li><li><strong>Plaintext in agent context</strong> — <code>arca run</code> injects values into the child&#39;s environment; the agent that spawned it sees the child&#39;s <em>output</em>, never the variable. <code>[secrets]</code> bounds the injectable surface so a <code>run</code> can&#39;t dump the whole vault.</li><li><strong>Accidental printing</strong> — <code>Secret</code> has no <code>Display</code>/<code>Debug</code> of the value (<code>.expose()</code> only), <code>list</code> is names + metadata only, and the TUI&#39;s posture is browse-never-spill (reveal is a deliberate two-step, audited).</li><li><strong>Ciphertext at rest, everywhere</strong> — every vault impl stores age ciphertext. The local file is unreadable without the identity; the <code>cf</code> remote store holds ciphertext over the wire <em>and</em> in D1 — a compromised worker yields blobs, not values. With <code>[vaults.*] private_refs = true</code> it can&#39;t even see <em>which</em> secrets exist: storage keys are HMAC-derived hex and the real ref travels in an age-encrypted <code>name</code> blob.</li><li><strong>Token leakage on the cf wire</strong> — scoped tokens (<code>ARCA_VAULT_TOKENS</code>) bound a leaked credential to its <code>{env, read, write}</code> scope instead of every env forever, and ArcaHmac request signing means the token never travels at all (a ±60s window bounds replay). All auth compares are constant-time.</li><li><strong>Silent misuse</strong> — every materialization, denial, and error emits an ndjson audit event on stderr, so capture is a wrapper away. <code>check</code> fails closed on a vault that won&#39;t decrypt, and on a mixed-mode cf vault (private config + plaintext rows).</li></ul><h2 id="does-not-protect-against" tabindex="-1">Does NOT protect against <a class="header-anchor" href="#does-not-protect-against" aria-label="Permalink to &quot;Does NOT protect against&quot;">​</a></h2><ul><li><strong>A determined local actor</strong> — <code>ARCA_ACTOR</code> is self-claimed (attribution, not identity) and <code>[guardrails]</code> are advisory: anyone who can edit <code>arca.toml</code> or run the binary can bypass them. They prevent <em>accidents</em>, not adversaries. Real multi-actor policy and enforcement belong to <strong>peregrin</strong>.</li><li><strong>The identity&#39;s host protection</strong> — the master key lives in the session keyring when one exists (ADR-0002), which protects it about as well as your login session. On headless/CI it is still <code>identity.txt</code> (0600), raw key material — protect it like a private SSH key. Either way, UID-level compromise reaches it: the keyring raises the bar, it is not a TPM.</li><li><strong>The child process</strong> — once <code>run</code> injects env vars, the child owns them (<code>/proc/&lt;pid&gt;/environ</code>, core dumps, the child logging its own env). arca&#39;s guarantee ends at <code>exec</code>.</li><li><strong>Deploy sinks</strong> — <code>arca deploy</code> pushes plaintext into the sink by design (CF Secrets Store is write-only); a sink compromise is outside arca&#39;s boundary — it crosses exactly once, at push.</li><li><strong>Access patterns</strong> — <code>private_refs</code> hides <em>which</em> secrets exist, not <em>when</em> they&#39;re touched: request timing and row counts are still observable to the store. Oblivious access is out of scope.</li><li><strong>Host compromise in general</strong> — an attacker who can read your memory, ptrace the broker, or impersonate your UID already won; arca raises the bar for <em>accidental</em> and <em>casual</em> leaks, not root.</li></ul><h2 id="in-one-line" tabindex="-1">In one line <a class="header-anchor" href="#in-one-line" aria-label="Permalink to &quot;In one line&quot;">​</a></h2><p>arca makes the <em>default</em> posture &quot;values never appear in repos, prompts, args, logs, or agent context&quot; — and records every time one still crosses.</p>',8)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
